main :: proc() {
	data := [7]int {
		128, 10, 7, 7, 1, -1, -13, 3, 1, 13,
	}

	result := 128

	for count in data {
		if entry_map(count, result) {
			fmt.printfln("%size entry amount level %size", count, result)
